# -*- coding: utf-8 -*-
"""
Заключение, Список источников и Приложение А (Спецификация компонентов)
для пояснительной записки «Разработка модуля персонализированных рекомендаций на основе машинного обучения».
"""

from docx.shared import Pt, Mm, RGBColor
from .styles import add_p, add_h1, add_table

def build_conclusion(doc):
    add_h1(doc, "ЗАКЛЮЧЕНИЕ", page_break=True)

    add_p(doc, "В ходе выполнения исследовательского проекта по теме «Разработка модуля персонализированных рекомендаций на основе машинного обучения (на примере музыкальной индустрии)» был разработан и всесторонне исследован программный комплекс интеллектуальных рекомендаций для электронной коммерции в музыкальной сфере на базе интернет-магазина «Synthesia». Проведенная работа объединила теоретический анализ современных алгоритмов машинного обучения с практической реализацией распределенного программного комплекса, включающего подсистему автоматизированного сбора данных, сервис векторного поиска и транзакционное ядро электронной коммерции.")

    add_p(doc, "В соответствии с поставленной целью и задачами исследования были получены следующие научно-практические результаты:")

    add_p(doc, "1. Выполнен аналитический обзор отечественного рынка музыкального ритейла на примере торговых платформ Muz.by, Tvoyzvuk.by, «Музторг» и «Аудиомания». Выявлена строгая изоляция каталогов инструментов и фонотек, обоснована необходимость сквозного связывания музыкальных альбомов с инструментами для их создания.", first_indent=12.5)

    add_p(doc, "2. Спроектирована архитектура программного комплекса интернет-магазина «Synthesia» на базе разделения контуров сбора данных, машинного обучения и транзакционного ядра, обеспечивающая масштабируемость и изоляцию вычислительных нагрузок.", first_indent=12.5)

    add_p(doc, "3. Разработана математическая модель плотного векторного пространства размерности 384 на базе предобученной языковой модели MiniLM-L12-v2 и спроектирован алгоритм агрегации треков релиза в нормализованный центроидный вектор по метрике косинусного сходства.", first_indent=12.5)

    add_p(doc, "4. Реализована подсистема автоматизированного сбора данных synesthesia-parser (Python 3.13), обеспечивающая сбор характеристик инструментов с pop-music.ru через библиотеку curl_cffi с обходом TLS-защиты, извлечение релизов из базы Discogs с контролем rate-limit и консольный импорт в базу данных через скрипт cli/catalog_ingest.php.", first_indent=12.5)

    add_p(doc, "5. Разработан высокопроизводительный микросервис машинного обучения на базе FastAPI и векторной базы данных Qdrant, реализующий быстрый поиск методом k ближайших соседей по графовому индексу HNSW.", first_indent=12.5)

    add_p(doc, "6. Создан модуль структурированного треклиста soundnet_tracklist для OpenCart LiveStore, исключающий необходимость медиа-хостинга тяжелых аудиофайлов, и адаптивная витрина магазина в темной цветовой гамме с интерактивным блоком персональных рекомендаций.", first_indent=12.5)

    add_p(doc, "7. Внедрена многоуровневая подсистема контроля отказоустойчивости StopKran (перехватчик фатальных ошибок Watchdog, механизм автоматического отключения сбойных модификаторов и аварийный консольный инструмент восстановления cli/stopkran.php).", first_indent=12.5)

    add_p(doc, "8. Проведен комплекс экспериментальных исследований: доказано сокращение задержки формирования рекомендаций более чем в 10 раз — до уровня 1.4–1.7 мс благодаря оперативной памяти Redis при доле попаданий в кэш 87.4%, и подтверждена 100% надежность прохождения автоматизированных тестов.", first_indent=12.5)

    add_p(doc, "Выдвинутая в исследовании гипотеза о том, что использование методов машинного обучения на основе векторных представлений и метрического анализа позволит построить устойчивую модель персонализированного подбора товаров в музыкальной сфере, связывающую фонографические релизы с инструментами звукового синтеза, а разработка специализированной программы сбора данных обеспечит автоматизированное наполнение структурированного каталога, полностью подтвердилась.")

